    settle: [0.22, 1, 0.36, 1],
    move: [0.65, 0, 0.35, 1],
    exit: [0.4, 0, 1, 1],
    linear: [0, 0, 1, 1],
  },
  spring: {
    pop: {
      type: "spring",
      stiffness: 420,
